import unicodedata


def slugify(s):
    s = s.lower()
    # Decompose so accented letters become a base char + combining marks,
    # then drop the marks (e.g. 'õ' -> 'o').
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(c for c in s if not unicodedata.combining(c))
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif out and out[-1] != '-':
            out.append('-')
    return ''.join(out).rstrip('-')

def slugify(s):
    s = s.lower()
    translit = {'õ': 'o', 'ä': 'a', 'ö': 'o', 'ü': 'u'}
    s = ''.join(translit.get(ch, ch) for ch in s)
    out = []
    prev_hyphen = False
    for ch in s:
        if ch.isalnum():
            out.append(ch)
            prev_hyphen = False
        else:
            if not prev_hyphen:
                out.append('-')
                prev_hyphen = True
    return ''.join(out).strip('-')

import unicodedata


def slugify(s):
    # Decompose to base characters and drop combining marks (e.g. õ -> o).
    s = unicodedata.normalize('NFKD', s).lower()
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif out and out[-1] != '-':
            out.append('-')
    # Strip a possible trailing dash.
    while out and out[-1] == '-':
        out.pop()
    return ''.join(out)

import unicodedata


def slugify(s):
    s = s.lower()
    s = unicodedata.normalize('NFKD', s)
    # Remove combining marks (diacritics) so õ -> o.
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif out and out[-1] != '-':
            out.append('-')
    while out and out[-1] == '-':
        out.pop()
    return ''.join(out)
